    TR("pt-nl","Toda a gente se mascara.", ["Iedereen verkleedt zich"], "Reflexivo.", ["v-zich-verkleden"]),
    TR("pt-nl","Vimos o desfile.", ["We hebben de optocht gezien","Wij hebben de optocht gezien","We zagen de optocht"], "optocht.", ["v-optocht"]),
