  ex=[("In de winter gaan veel Nederlanders schaatsen.","No inverno muitos neerlandeses vão patinar."),("De Elfstedentocht gaat langs elf Friese steden.","A Elfstedentocht passa por onze cidades frísias."),("De kanalen moeten helemaal dichtvriezen.","Os canais têm de congelar por completo."),("De tocht is heel zeldzaam geworden.","A prova tornou-se muito rara.")],
