    FE(["Wij","gaan","in","kraamvisite."], 2, "op", "op kraamvisite gaan.", ["v-kraamvisite"]),
    FB("We hebben een mooi ___ gekregen met een foto van de baby.", ["geboortekaartje"], "Cartão de nascimento.", ["v-geboortekaartje"], choices=["geboortekaartje","kraamvisite","beschuit"], tr="Recebemos um cartão de nascimento bonito com uma foto do bebé."),
    LI("Wil je een beschuitje met muisjes?", ["Wil je een beschuitje met muisjes","Wil je een beschuitje met muisjes?"], "Queres uma tostinha com confeitos?", "Oferta clássica.", ["v-beschuit-met-muisjes"]),
