L(17, "Dia da Mãe e do Pai", "Ontbijt op bed voor mama.",
  ["Falar das celebrações do Dia da Mãe e do Pai"],
  vocab=[V("v-moederdag","Moederdag","Dia da Mãe","noun","de"), V("v-vaderdag","Vaderdag","Dia do Pai","noun","de"),
         V("v-ontbijt-op-bed","ontbijt op bed","pequeno-almoço na cama","expression"), V("v-knutselen","knutselen","fazer trabalhos manuais","verb")],
  ex=[("Op Moederdag krijgt mama ontbijt op bed.","No Dia da Mãe a mãe recebe pequeno-almoço na cama."),("De kinderen hebben op school iets geknutseld.","As crianças fizeram um trabalho manual na escola."),("Vaderdag is in Nederland in juni.","O Dia do Pai nos Países Baixos é em junho.")],
  review=["v-cadeau","v-ontbijt"],
  cefr=C, exs=[
    MA([("Moederdag","Dia da Mãe"),("Vaderdag","Dia do Pai"),("ontbijt op bed","pequeno-almoço na cama"),("knutselen","fazer trabalhos manuais")], "Família.", ["v-moederdag","v-vaderdag","v-ontbijt-op-bed","v-knutselen"]),
    MC("Uma diferença com Portugal:", ["*o Dia do Pai nos Países Baixos é em junho, em Portugal a 19 de março","são no mesmo dia|Não.","Portugal não tem Dia do Pai|Tem."], "Datas.", ["v-vaderdag"]),
    MC("Nos Países Baixos, o Dia da Mãe é…", ["*no segundo domingo de maio","no primeiro domingo de maio (como em Portugal)|Em Portugal é o primeiro; nos Países Baixos o segundo.","em dezembro|Não."], "Datas diferentes.", ["v-moederdag"]),
    TR("pt-nl","A mãe recebe pequeno-almoço na cama.", ["Mama krijgt ontbijt op bed","Moeder krijgt ontbijt op bed"], "ontbijt op bed.", ["v-ontbijt-op-bed"]),
    CJ("knutselen","de kinderen","De kinderen hebben een kaart ___.", ["geknutseld"], "ge-knutsel-d.", ["v-knutselen"], tense="passado-perfeito"),
    CO("text","Moederdag", "Op Moederdag maken veel kinderen ontbijt op bed voor hun moeder. Op de basisschool knutselen ze in de week ervoor een cadeautje, bijvoorbeeld een tekening of een bloempot. Volwassen kinderen gaan vaak op bezoek of nemen hun moeder mee uit eten. In juni is het Vaderdag, met vaak dezelfde tradities.",
       [("O que fazem as crianças pequenas?", ["*Fazem um presente na escola","Compram joias","Nada"]),("E os filhos adultos?", ["*Visitam ou levam a mãe a jantar","Mandam só uma mensagem","Ficam em casa"]),("Quando é o Dia do Pai?", ["*Em junho","Em março","Em maio"])],
       "Tradições de família.", ["v-moederdag","v-knutselen","v-vaderdag"]),
    FE(["Op","Moederdag","krijg","mijn","moeder","ontbijt","op","bed."], 2, "krijgt", "Sujeito: mijn moeder → krijgt.", ["v-ontbijt-op-bed"]),
    FB("Mijn zoontje heeft een mooie kaart ___ voor Vaderdag.", ["geknutseld"], "Feito à mão.", ["v-knutselen"], choices=["geknutseld","gekocht","gestuurd"], tr="O meu filho fez um postal bonito para o Dia do Pai."),
    LI("Wat geef jij je moeder voor Moederdag?", ["Wat geef jij je moeder voor Moederdag","Wat geef jij je moeder voor Moederdag?"], "O que dás à tua mãe no Dia da Mãe?", "Pergunta.", ["v-moederdag"]),
    WO("O Dia do Pai é em junho.", ["Vaderdag","is","in","juni"], "Ordem.", ["v-vaderdag"]),
  ], diff=3, mins=6)

