    DL([("Vriend","Doe je mee met de nieuwjaarsduik?","Alinhas no mergulho de Ano Novo?"),("Jij","","")], ["*Ben je gek? Daar heb ik de moed niet voor! Ik kom wel kijken.","Ja, ik duik gisteren.|Tempo errado.","Ik ben ijskoud water.|Não faz sentido."], "Recusar com humor.", ["v-moed"]),
    FE(["Het","water","waren","ijskoud."], 2, "was", "Singular: was.", ["v-ijskoud-water"]),
    FB("Je hebt veel ___ nodig om in de winter te zwemmen.", ["moed"], "Coragem.", ["v-moed"], choices=["moed","water","muts"], tr="Precisas de muita coragem para nadar no inverno."),
