    TR("pt-nl","Cada bairro está decorado.", ["Elke wijk is versierd"], "versierd.", ["v-wijk"]),
    TR("pt-nl","Toda a gente come sardinhas assadas.", ["Iedereen eet gegrilde sardines"], "iedereen + singular.", ["v-gegrilde-sardines"]),
    MC("Em São João, no Porto, é tradição…", ["*dar com martelos de plástico na cabeça das pessoas","atirar ovos|Não.","ficar em silêncio|Não."], "Curiosidade.", ["v-volksfeest"]),
    FE(["Iedereen","eten","sardines."], 1, "eet", "Iedereen + singular: eet.", ["v-gegrilde-sardines"]),
    FB("Alfama is een oude ___ in Lissabon.", ["wijk"], "Bairro.", ["v-wijk"], choices=["wijk","feest","heilige"], tr="Alfama é um bairro antigo de Lisboa."),
    LI("In juni ruik je overal gegrilde sardines.", ["In juni ruik je overal gegrilde sardines"], "Em junho cheira-se a sardinhas assadas em todo o lado.", "ruiken.", ["v-gegrilde-sardines"]),
    SW("Explique a um colega neerlandês uma tradição portuguesa (5–6 frases): quando, onde, o que se faz, o que se come.", ["In Portugal vieren we op 11 november São Martinho. Het is een herfstfeest. We poffen kastanjes op straat of thuis. Daarbij drinken we jonge wijn of «água-pé». Er wordt gezegd dat het die dagen vaak mooi weer is: de «zomer van São Martinho». Het lijkt een beetje op Sint-Maarten in Nederland, maar zonder lampions!"], ["Quando e onde", "O que se faz", "Comida/bebida", "Uma comparação com os Países Baixos"], 55, "Explicar uma tradição.", ["v-volksfeest","v-traditie"]),
